import type {
  FeatureActionPolicy,
  FeatureActionResult,
  FeaturePackError,
  FeaturePackResource
} from '../shared/feature-pack-contracts';

export type AuthEntryMode =
  | 'sign-in'
  | 'sign-up'
  | 'recover-password'
  | 'reset-password';

export type AuthFlowState =
  | Readonly<{ status: 'entry'; mode: 'sign-in' | 'sign-up' }>
  | Readonly<{ status: 'recovery'; phase: 'request' | 'sent' }>
  | Readonly<{
      status: 'callback';
      kind: 'account-deletion' | 'email-verification' | 'password-reset';
      phase: 'ready' | 'processing' | 'success' | 'invalid' | 'expired' | 'reused' | 'error';
      message?: string;
    }>
  | Readonly<{
      status: 'account';
      screen: 'overview' | 'security' | 'connected-accounts' | 'devices' | 'sessions';
    }>
  | Readonly<{
      status: 'step-up';
      method: 'password';
      reason: 'account-deletion' | 'connected-account-disconnect' | string;
    }>
  | Readonly<{
      status: 'challenge';
      method: Exclude<AuthMethod, 'password'>;
      step: string;
    }>;

export type AuthMethod =
  | 'password'
  | 'email-otp'
  | 'sms-otp'
  | 'totp'
  | 'passkey'
  | 'oauth';

/**
 * Public, credential-free state that a trusted auth contribution may hand to
 * the feature pack. Backend challenge tokens stay in the contribution's own
 * closure or credential vault and must never be placed in this descriptor.
 */
export type AuthChallengeDescriptor = Readonly<{
  id: string;
  title: string;
  description?: string;
}>;

export type AuthChallengeResponse =
  | Readonly<{ kind: 'code'; code: string }>
  | Readonly<{ kind: 'redirect'; callbackUrl: string }>
  | Readonly<{ kind: 'webauthn'; credential: unknown }>
  | Readonly<{ kind: 'custom'; value: unknown }>;

type AuthChallengeResponseKind = AuthChallengeResponse['kind'];
type ProviderChallengeResponseKind = Exclude<AuthChallengeResponseKind, 'code'>;

type AuthChallengeResponseFor<
  Kind extends AuthChallengeResponseKind
> = Extract<AuthChallengeResponse, { kind: Kind }>;

type AuthChallengeContributionBase = Readonly<{
  method: Exclude<AuthMethod, 'password'>;
  label: string;
  start: (input: Readonly<{ email?: string; returnTo?: string }>) =>
    Promise<AuthChallengeDescriptor>;
  cancel?: (input: Readonly<{ challengeId: string }>) => FeatureActionResult;
}>;

type AuthCodeChallengeContribution = AuthChallengeContributionBase & Readonly<{
  response: 'code';
  complete: (input: Readonly<{
    challengeId: string;
    response: AuthChallengeResponseFor<'code'>;
  }>) => FeatureActionResult;
}>;

type AuthProviderChallengeContribution<
  Kind extends ProviderChallengeResponseKind
> = AuthChallengeContributionBase & Readonly<{
  response: Kind;
  /** Provider-owned response acquisition for redirect, WebAuthn, or custom challenges. */
  respond: (input: Readonly<{
    challenge: AuthChallengeDescriptor;
  }>) => AuthChallengeResponseFor<Kind> | Promise<AuthChallengeResponseFor<Kind>>;
  complete: (input: Readonly<{
    challengeId: string;
    response: AuthChallengeResponseFor<Kind>;
  }>) => FeatureActionResult;
}>;

/**
 * A contribution is complete by construction: code challenges are collected
 * by the feature pack, while every provider-owned response kind requires its
 * matching response handler and completion callback.
 */
export type AuthChallengeContribution =
  | AuthCodeChallengeContribution
  | {
      [Kind in ProviderChallengeResponseKind]:
        AuthProviderChallengeContribution<Kind>;
    }[ProviderChallengeResponseKind];

export type AuthPasswordPolicy = Readonly<{
  minLength?: number;
  maxLength?: number;
  hint?: string;
  validate?: (password: string) => string | undefined;
}>;

export type AuthIdentity = Readonly<{
  id: string;
  displayName: string;
  primaryEmail: string;
  avatarUrl?: string;
  emailVerified?: boolean;
  createdAt?: string;
}>;

export type AuthSession = Readonly<{
  id: string;
  current?: boolean;
  deviceLabel: string;
  location?: string;
  lastSeenAt?: string;
}>;

export type AuthConnectedAccount = Readonly<{
  id: string;
  service: string;
  identifier: string;
  isVerified?: boolean;
  createdAt?: string;
}>;

export type AuthAccountData = Readonly<{
  identity: AuthIdentity;
  sessions?: readonly AuthSession[];
  connectedAccounts?: readonly AuthConnectedAccount[];
}>;

export type AuthFeatureAction =
  | 'signIn'
  | 'signUp'
  | 'recoverPassword'
  | 'resetPassword'
  | 'sendVerificationEmail'
  | 'signOut'
  | 'updateProfile'
  | 'changePassword'
  | 'verifyPassword'
  | 'requestAccountDeletion'
  | 'disconnectConnectedAccount'
  | 'revokeSession';

export type AuthFeatureActions = Readonly<{
  signIn?: (input: {
    email: string;
    password: string;
    rememberMe?: boolean;
  }) => FeatureActionResult;
  signUp?: (input: {
    email: string;
    password: string;
    rememberMe?: boolean;
  }) => FeatureActionResult;
  recoverPassword?: (input: { email: string }) => FeatureActionResult;
  resetPassword?: (input: { password: string }) => FeatureActionResult;
  sendVerificationEmail?: (input: { email: string }) => FeatureActionResult;
  signOut?: () => FeatureActionResult;
  updateProfile?: (input: { displayName: string }) => FeatureActionResult;
  changePassword?: (input: {
    currentPassword: string;
    newPassword: string;
  }) => FeatureActionResult;
  verifyPassword?: (input: { password: string }) => FeatureActionResult;
  requestAccountDeletion?: (input: { password: string }) => FeatureActionResult;
  disconnectConnectedAccount?: (input: {
    accountId: string;
    password: string;
  }) => FeatureActionResult;
  revokeSession?: (input: { sessionId: string }) => FeatureActionResult;
}>;

export type AuthFeatureNotice = Readonly<{
  status: 'error' | 'success';
  message: string;
}>;

export type AuthAccountSection =
  | 'profile'
  | 'security'
  | 'connected-accounts'
  | 'sessions';

export type AuthFeaturePackProps = Readonly<{
  view: 'entry' | 'account';
  account?: FeaturePackResource<AuthAccountData>;
  notice?: AuthFeatureNotice;
  /** @deprecated Use notice for callback and verification feedback. */
  verificationNotice?: AuthFeatureNotice;
  mode?: AuthEntryMode;
  passwordPolicy?: AuthPasswordPolicy;
  challengeContributions?: readonly AuthChallengeContribution[];
  policy?: FeatureActionPolicy<AuthFeatureAction>;
  actions?: AuthFeatureActions;
  onModeChange?: (mode: AuthEntryMode) => void;
  onAuthenticated?: () => void;
  accountSection?: AuthAccountSection;
  defaultAccountSection?: AuthAccountSection;
  onAccountSectionChange?: (section: AuthAccountSection) => void;
  onError?: (error: FeaturePackError) => void;
}>;

'use client';

import * as React from 'react';
import {
  ArrowLeftIcon,
  EyeIcon,
  EyeOffIcon,
  KeyRoundIcon,
  LockKeyholeIcon,
  MailIcon
} from 'lucide-react';

import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle
} from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Field, FieldGroup, FieldLabel } from '@/components/ui/field';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput
} from '@/components/ui/input-group';

import { canPerform, normalizeFeaturePackError } from '../shared/feature-pack-contracts';
import type {
  AuthEntryMode,
  AuthFeaturePackProps
} from './auth-contracts';
import {
  authPasswordHint,
  authPasswordPolicyError,
  normalizedPasswordLength
} from './auth-password-policy';
import { AuthChallengePanel } from './auth-challenge-panel';

const modeCopy: Record<
  AuthEntryMode,
  Readonly<{ title: string; description: string; submit: string; pending: string }>
> = {
  'sign-in': {
    title: 'Sign in',
    description: 'Use your account to continue to this application.',
    submit: 'Sign in',
    pending: 'Signing in…'
  },
  'sign-up': {
    title: 'Create an account',
    description: 'Create credentials for your personal Constructive identity.',
    submit: 'Create account',
    pending: 'Creating account…'
  },
  'recover-password': {
    title: 'Recover your account',
    description: 'We will send recovery instructions when an account can receive them.',
    submit: 'Send recovery email',
    pending: 'Sending recovery email…'
  },
  'reset-password': {
    title: 'Choose a new password',
    description: 'Set a new password to finish recovering your account.',
    submit: 'Reset password',
    pending: 'Resetting password…'
  }
};

function actionForMode(mode: AuthEntryMode) {
  if (mode === 'sign-in') return 'signIn' as const;
  if (mode === 'sign-up') return 'signUp' as const;
  if (mode === 'recover-password') return 'recoverPassword' as const;
  return 'resetPassword' as const;
}

export function AuthEntryPanel({
  mode = 'sign-in',
  policy,
  actions,
  notice,
  verificationNotice,
  passwordPolicy,
  challengeContributions = [],
  onModeChange,
  onAuthenticated,
  onError
}: Omit<AuthFeaturePackProps, 'view' | 'account'>) {
  const [email, setEmail] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [rememberMe, setRememberMe] = React.useState(false);
  const [showPassword, setShowPassword] = React.useState(false);
  const [pending, setPending] = React.useState(false);
  const [feedback, setFeedback] = React.useState<string>();
  const [error, setError] = React.useState<string>();
  const [emailError, setEmailError] = React.useState<string>();
  const [passwordError, setPasswordError] = React.useState<string>();
  const fieldId = React.useId();
  const emailRef = React.useRef<HTMLInputElement>(null);
  const passwordRef = React.useRef<HTMLInputElement>(null);
  const copy = modeCopy[mode];
  const modeAvailable = (candidate: AuthEntryMode) => {
    const action = actionForMode(candidate);
    return canPerform(policy, action) && Boolean(actions?.[action]);
  };
  const allowed = modeAvailable(mode);
  const canRecoverPassword = Boolean(onModeChange) && modeAvailable('recover-password');
  const canSignUp = Boolean(onModeChange) && modeAvailable('sign-up');
  const canSignIn = Boolean(onModeChange) && modeAvailable('sign-in');
  const requiresPassword = mode !== 'recover-password';
  const requiresStrongPassword = mode === 'sign-up' || mode === 'reset-password';
  const passwordHint = requiresStrongPassword
    ? authPasswordHint(password, passwordPolicy)
    : undefined;
  const emailErrorId = `${fieldId}-email-error`;
  const passwordDescriptionId = `${fieldId}-password-description`;
  const passwordErrorId = `${fieldId}-password-error`;
  const passwordDescribedBy = passwordHint && passwordError
    ? `${passwordDescriptionId} ${passwordErrorId}`
    : passwordHint
      ? passwordDescriptionId
      : passwordError
        ? passwordErrorId
        : undefined;
  const minPasswordLength = normalizedPasswordLength(passwordPolicy?.minLength);
  const maxPasswordLength = normalizedPasswordLength(passwordPolicy?.maxLength);
  const activeNotice = notice ?? verificationNotice;

  React.useEffect(() => {
    setPassword('');
    setRememberMe(false);
    setError(undefined);
    setFeedback(undefined);
    setEmailError(undefined);
    setPasswordError(undefined);
    setShowPassword(false);
  }, [mode]);

  const focusFirstError = (next: Readonly<{ email?: string; password?: string }>) => {
    if (next.email) {
      emailRef.current?.focus();
      return;
    }
    if (next.password) {
      passwordRef.current?.focus();
    }
  };

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!allowed) return;

    const nextEmailError =
      mode !== 'reset-password' && !email.trim()
        ? 'Enter an email address.'
        : undefined;
    const nextPasswordError = requiresPassword
      ? !password
        ? 'Enter a password.'
        : requiresStrongPassword
          ? authPasswordPolicyError(password, passwordPolicy)
          : undefined
      : undefined;

    setEmailError(nextEmailError);
    setPasswordError(nextPasswordError);
    setError(undefined);
    setFeedback(undefined);

    if (nextEmailError || nextPasswordError) {
      focusFirstError({ email: nextEmailError, password: nextPasswordError });
      return;
    }

    setPending(true);

    try {
      if (mode === 'sign-in') {
        if (!actions?.signIn) return;
        await actions.signIn({ email: email.trim(), password, rememberMe });
        onAuthenticated?.();
      } else if (mode === 'sign-up') {
        if (!actions?.signUp) return;
        await actions.signUp({
          email: email.trim(),
          password,
          rememberMe
        });
        setFeedback('Check your email to confirm your address, then sign in with your password.');
      } else if (mode === 'recover-password') {
        if (!actions?.recoverPassword) return;
        await actions.recoverPassword({ email: email.trim() });
        setFeedback('If that address can receive recovery email, instructions are on the way.');
      } else {
        if (!actions?.resetPassword) return;
        await actions.resetPassword({ password });
        setFeedback('Your password has been reset. You can sign in now.');
      }
    } catch (cause) {
      const normalized = normalizeFeaturePackError(cause, 'Authentication could not be completed.');
      setError(normalized.message);
      onError?.(normalized);
      // Keep focus near the credentials so the alert is announced next to the action.
      if (requiresPassword) {
        passwordRef.current?.focus();
      } else {
        emailRef.current?.focus();
      }
    } finally {
      setPending(false);
    }
  };

  return (
    <div className='flex min-h-[min(36rem,calc(100dvh-8rem))] items-center justify-center py-2 sm:py-6'>
      <Card className='w-full max-w-sm gap-0 border-0 py-0 shadow-card' variant='flat'>
        <CardHeader className='gap-1 px-6 pt-6 pb-4'>
          <div className='bg-primary/10 text-primary ring-primary/20 mb-3 grid size-9 place-items-center rounded-[10px] ring-1 ring-inset'>
            <KeyRoundIcon aria-hidden='true' className='size-4' />
          </div>
          <CardTitle>
            <h1 className='text-balance text-lg font-medium tracking-tight'>
              {copy.title}
            </h1>
          </CardTitle>
          <CardDescription className='text-pretty text-[13px]'>{copy.description}</CardDescription>
        </CardHeader>
        <form noValidate onSubmit={(event) => void submit(event)}>
          <CardContent className='flex flex-col gap-4 px-6 pb-6'>
            {activeNotice ? (
              <Alert
                role={activeNotice.status === 'error' ? 'alert' : 'status'}
                variant={activeNotice.status === 'error' ? 'destructive' : 'default'}
              >
                <AlertDescription>{activeNotice.message}</AlertDescription>
              </Alert>
            ) : null}
            <FieldGroup>
              {mode !== 'reset-password' ? (
                <Field
                  error={emailError}
                  errorId={emailErrorId}
                  htmlFor={`${fieldId}-email`}
                  label='Email address'
                  required
                >
                  <InputGroup>
                    <InputGroupAddon>
                      <MailIcon aria-hidden='true' />
                    </InputGroupAddon>
                    <InputGroupInput
                      aria-describedby={emailError ? emailErrorId : undefined}
                      aria-invalid={emailError ? true : undefined}
                      autoComplete='email'
                      autoCapitalize='none'
                      id={`${fieldId}-email`}
                      name='email'
                      onChange={(event) => {
                        setEmail(event.currentTarget.value);
                        if (emailError) setEmailError(undefined);
                      }}
                      ref={emailRef}
                      required
                      spellCheck={false}
                      type='email'
                      value={email}
                    />
                  </InputGroup>
                </Field>
              ) : null}
              {requiresPassword ? (
                <Field
                  description={passwordHint}
                  descriptionId={passwordDescriptionId}
                  error={passwordError}
                  errorId={passwordErrorId}
                  htmlFor={`${fieldId}-password`}
                  label={mode === 'reset-password' ? 'New password' : 'Password'}
                  required
                >
                  <InputGroup>
                    <InputGroupAddon>
                      <LockKeyholeIcon aria-hidden='true' />
                    </InputGroupAddon>
                    <InputGroupInput
                      aria-describedby={passwordDescribedBy}
                      aria-invalid={passwordError ? true : undefined}
                      autoComplete={mode === 'sign-in' ? 'current-password' : 'new-password'}
                      id={`${fieldId}-password`}
                      maxLength={requiresStrongPassword ? maxPasswordLength : undefined}
                      minLength={requiresStrongPassword ? minPasswordLength : undefined}
                      name='password'
                      onChange={(event) => {
                        setPassword(event.currentTarget.value);
                        if (passwordError) setPasswordError(undefined);
                      }}
                      ref={passwordRef}
                      required
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                    />
                    <InputGroupAddon align='inline-end'>
                      <Button
                        aria-label={showPassword ? 'Hide password' : 'Show password'}
                        aria-pressed={showPassword}
                        className='size-7 p-0'
                        onClick={() => setShowPassword((value) => !value)}
                        size='sm'
                        type='button'
                        variant='ghost'
                      >
                        {showPassword
                          ? <EyeOffIcon aria-hidden='true' />
                          : <EyeIcon aria-hidden='true' />}
                      </Button>
                    </InputGroupAddon>
                  </InputGroup>
                </Field>
              ) : null}
              {mode === 'sign-in' || mode === 'sign-up' ? (
                <Field orientation='horizontal'>
                  <Checkbox
                    checked={rememberMe}
                    id={`${fieldId}-remember-me`}
                    name='remember-me'
                    onCheckedChange={(checked) => setRememberMe(checked === true)}
                  />
                  <FieldLabel htmlFor={`${fieldId}-remember-me`}>
                    Keep me signed in on this device
                  </FieldLabel>
                </Field>
              ) : null}
            </FieldGroup>
            {error ? (
              <Alert role='alert' variant='destructive'>
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            ) : null}
            {feedback ? (
              <Alert role='status'>
                <AlertDescription>{feedback}</AlertDescription>
              </Alert>
            ) : null}
            {!allowed ? (
              <p className='text-muted-foreground text-pretty text-sm'>
                This authentication action is unavailable for the current app.
              </p>
            ) : null}
            <Button
              aria-busy={pending}
              disabled={!allowed || pending}
              type='submit'
            >
              {pending ? copy.pending : copy.submit}
            </Button>
          </CardContent>
        </form>
        {mode === 'sign-in' ? (
          <AuthChallengePanel
            contributions={challengeContributions}
            email={email}
            onAuthenticated={onAuthenticated}
            onError={onError}
          />
        ) : null}
        {mode === 'sign-in' && (canRecoverPassword || canSignUp) ? (
          <CardFooter className='flex flex-wrap items-center justify-between gap-2 border-t border-dashed border-foreground/10 bg-muted/30 px-6 py-3 text-[13px]'>
            {canRecoverPassword ? (
              <button className='text-muted-foreground hover:text-foreground cursor-pointer rounded outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50' onClick={() => onModeChange?.('recover-password')} type='button'>
                Forgot password?
              </button>
            ) : <span />}
            {canSignUp ? (
              <span className='text-muted-foreground'>
                New here?{' '}
                <button className='text-primary cursor-pointer rounded font-medium outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50' onClick={() => onModeChange?.('sign-up')} type='button'>
                  Create account
                </button>
              </span>
            ) : null}
          </CardFooter>
        ) : mode !== 'sign-in' && canSignIn ? (
          <CardFooter className='flex flex-wrap justify-between gap-2 border-t border-dashed border-foreground/10 bg-muted/30 px-6 py-2'>
            <Button onClick={() => onModeChange?.('sign-in')} size='sm' variant='ghost'>
              <ArrowLeftIcon data-icon='inline-start' />
              Back to sign in
            </Button>
          </CardFooter>
        ) : null}
      </Card>
    </div>
  );
}

'use client';

import * as React from 'react';

import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { CardContent } from '@/components/ui/card';
import { Field } from '@/components/ui/field';
import { Input } from '@/components/ui/input';

import { normalizeFeaturePackError } from '../shared/feature-pack-contracts';
import type {
  AuthChallengeContribution,
  AuthChallengeDescriptor,
  AuthFeaturePackProps
} from './auth-contracts';

type CodeChallengeContribution = Extract<
  AuthChallengeContribution,
  { response: 'code' }
>;

type ActiveChallenge = Readonly<{
  contribution: CodeChallengeContribution;
  descriptor: AuthChallengeDescriptor;
}>;

export function AuthChallengePanel({
  contributions,
  email,
  onAuthenticated,
  onError
}: Readonly<{
  contributions: readonly AuthChallengeContribution[];
  email: string;
  onAuthenticated?: AuthFeaturePackProps['onAuthenticated'];
  onError?: AuthFeaturePackProps['onError'];
}>) {
  const [active, setActive] = React.useState<ActiveChallenge>();
  const [code, setCode] = React.useState('');
  const [pending, setPending] = React.useState<string>();
  const [error, setError] = React.useState<string>();
  const [feedback, setFeedback] = React.useState<string>();
  const fieldId = React.useId();
  const errorId = `${fieldId}-code-error`;

  if (contributions.length === 0) return null;

  const reportError = (cause: unknown, fallback: string) => {
    const normalized = normalizeFeaturePackError(cause, fallback);
    setError(normalized.message);
    onError?.(normalized);
  };

  const completeCodeChallenge = async (
    contribution: CodeChallengeContribution,
    descriptor: AuthChallengeDescriptor,
    codeResponse: string
  ) => {
    await contribution.complete({
      challengeId: descriptor.id,
      response: { kind: 'code', code: codeResponse }
    });
    setActive(undefined);
    setCode('');
    setFeedback(`${contribution.label} authentication completed.`);
    onAuthenticated?.();
  };

  const start = async (contribution: AuthChallengeContribution, index: number) => {
    const pendingKey = `start-${index}`;
    setPending(pendingKey);
    setError(undefined);
    setFeedback(undefined);
    try {
      const descriptor = await contribution.start({
        email: email.trim() || undefined,
        returnTo: typeof window === 'undefined' ? undefined : window.location.href
      });
      if (contribution.response === 'code') {
        setActive({ contribution, descriptor });
        setCode('');
        return;
      }

      if (contribution.response === 'redirect') {
        const response = await contribution.respond({ challenge: descriptor });
        await contribution.complete({ challengeId: descriptor.id, response });
      } else if (contribution.response === 'webauthn') {
        const response = await contribution.respond({ challenge: descriptor });
        await contribution.complete({ challengeId: descriptor.id, response });
      } else {
        const response = await contribution.respond({ challenge: descriptor });
        await contribution.complete({ challengeId: descriptor.id, response });
      }
      setFeedback(`${contribution.label} authentication completed.`);
      onAuthenticated?.();
    } catch (cause) {
      reportError(cause, `${contribution.label} authentication could not be started.`);
    } finally {
      setPending(undefined);
    }
  };

  const submitCode = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!active || pending) return;
    const responseCode = code.trim();
    if (!responseCode) {
      setError('Enter the verification code.');
      return;
    }
    setPending('complete');
    setError(undefined);
    setFeedback(undefined);
    try {
      await completeCodeChallenge(
        active.contribution,
        active.descriptor,
        responseCode
      );
    } catch (cause) {
      reportError(cause, `${active.contribution.label} authentication could not be completed.`);
    } finally {
      setPending(undefined);
    }
  };

  const cancel = async () => {
    if (!active || pending) return;
    setPending('cancel');
    setError(undefined);
    try {
      await active.contribution.cancel?.({
        challengeId: active.descriptor.id
      });
      setActive(undefined);
      setCode('');
    } catch (cause) {
      reportError(cause, `${active.contribution.label} authentication could not be canceled.`);
    } finally {
      setPending(undefined);
    }
  };

  return (
    <CardContent className='mt-6 flex flex-col gap-4 border-t pt-6'>
      {active ? (
        <form
          aria-busy={Boolean(pending)}
          className='flex flex-col gap-4'
          onSubmit={(event) => void submitCode(event)}
        >
          <div>
            <h2 className='text-balance text-sm font-semibold'>{active.descriptor.title}</h2>
            {active.descriptor.description ? (
              <p className='text-muted-foreground mt-1 text-pretty text-sm'>
                {active.descriptor.description}
              </p>
            ) : null}
          </div>
          <Field
            error={error}
            errorId={errorId}
            htmlFor={`${fieldId}-code`}
            label='Verification code'
            required
          >
            <Input
              aria-describedby={error ? errorId : undefined}
              aria-invalid={error ? true : undefined}
              autoCapitalize='none'
              autoComplete='one-time-code'
              id={`${fieldId}-code`}
              inputMode='numeric'
              name='verification-code'
              onChange={(event) => {
                setCode(event.currentTarget.value);
                if (error) setError(undefined);
              }}
              required
              spellCheck={false}
              value={code}
            />
          </Field>
          <div className='flex flex-wrap gap-2'>
            <Button
              aria-busy={pending === 'complete'}
              disabled={!code.trim() || Boolean(pending)}
              type='submit'
            >
              {pending === 'complete' ? 'Verifying…' : 'Verify code'}
            </Button>
            <Button
              aria-busy={pending === 'cancel'}
              disabled={Boolean(pending)}
              onClick={() => void cancel()}
              type='button'
              variant='ghost'
            >
              {pending === 'cancel' ? 'Canceling…' : 'Use another method'}
            </Button>
          </div>
        </form>
      ) : (
        <div className='flex flex-col gap-3'>
          <div>
            <h2 className='text-balance text-sm font-semibold'>More ways to sign in</h2>
            <p className='text-muted-foreground mt-1 text-pretty text-sm'>
              Use an authentication method configured by this application.
            </p>
          </div>
          <div className='grid gap-2'>
            {contributions.map((contribution, index) => (
              <Button
                disabled={Boolean(pending)}
                key={`${contribution.method}-${contribution.label}`}
                onClick={() => void start(contribution, index)}
                type='button'
                variant='outline'
              >
                {pending === `start-${index}`
                  ? `Starting ${contribution.label}…`
                  : contribution.label}
              </Button>
            ))}
          </div>
          {error ? (
            <Alert role='alert' variant='destructive'>
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          ) : null}
          {feedback ? (
            <Alert role='status'>
              <AlertDescription>{feedback}</AlertDescription>
            </Alert>
          ) : null}
        </div>
      )}
    </CardContent>
  );
}

