);

/**
 * Identity hub: hero strip for who you are, underline sections for what you do.
 * Rejects nested “tabs-inside-cards” chrome in favor of a single calm settings surface.
 */
export function AuthAccountView({
  account = { status: 'loading' },
  policy,
  actions,
  notice,
  verificationNotice,
  passwordPolicy,
  accountSection,
  defaultAccountSection = 'profile',
  onAccountSectionChange,
  onError
}: Omit<AuthFeaturePackProps, 'view' | 'mode' | 'onModeChange' | 'onAuthenticated'>) {
  const [displayName, setDisplayName] = React.useState('');
  const [currentPassword, setCurrentPassword] = React.useState('');
  const [newPassword, setNewPassword] = React.useState('');
  const [showCurrentPassword, setShowCurrentPassword] = React.useState(false);
  const [showNewPassword, setShowNewPassword] = React.useState(false);
  const [pendingAction, setPendingAction] = React.useState<string>();
  const [sessionToRevoke, setSessionToRevoke] = React.useState<Readonly<{
    id: string;
    deviceLabel: string;
  }>>();
  const [verificationMessage, setVerificationMessage] = React.useState<Readonly<{
    kind: 'error' | 'success';
    text: string;
  }>>();
  const [uncontrolledSection, setUncontrolledSection] =
    React.useState<AuthAccountSection>(defaultAccountSection);
  const [actionError, setActionError] = React.useState<Readonly<{
    key: string;
    message: string;
  }>>();
  const actionGenerationRef = React.useRef(0);
  const pendingActionRef = React.useRef<string | undefined>(undefined);
  const fieldIdPrefix = React.useId();
  const displayNameId = `${fieldIdPrefix}-display-name`;
  const currentPasswordId = `${fieldIdPrefix}-current-password`;
  const newPasswordId = `${fieldIdPrefix}-new-password`;
  const activeNotice = notice ?? verificationNotice;
  const identityId = account.status === 'ready' ? account.data.identity.id : undefined;
  const section = accountSection ?? uncontrolledSection;

  const changeSection = (nextSection: AuthAccountSection) => {
    if (accountSection === undefined) setUncontrolledSection(nextSection);
    setActionError(undefined);
    onAccountSectionChange?.(nextSection);
  };

  React.useEffect(() => {
    actionGenerationRef.current += 1;
    pendingActionRef.current = undefined;
    setPendingAction(undefined);
    setCurrentPassword('');
    setNewPassword('');
    setShowCurrentPassword(false);
    setShowNewPassword(false);
    setSessionToRevoke(undefined);
    setActionError(undefined);
  }, [identityId]);

  const run = async (
    key: string,
    action: () => FeatureActionResult,
    fallback: string,
    onSuccess?: () => void,
    onFailure?: (message: string) => void
  ) => {
    if (pendingActionRef.current) return;
    const generation = actionGenerationRef.current;
    pendingActionRef.current = key;
    setPendingAction(key);
    setActionError(undefined);
    try {
      await action();
      if (actionGenerationRef.current !== generation) return;
      onSuccess?.();
    } catch (cause) {
      if (actionGenerationRef.current !== generation) return;
      const error = normalizeFeaturePackError(cause, fallback);
      onError?.(error);
      if (onFailure) {
        onFailure(error.message);
      } else {
        setActionError({ key, message: error.message });
      }
    } finally {
      if (actionGenerationRef.current === generation) {
        pendingActionRef.current = undefined;
        setPendingAction(undefined);
      }
    }
  };

  return (
    <div className='mx-auto flex w-full max-w-2xl flex-col gap-6'>
      <h1 className='sr-only'>Account</h1>
      {activeNotice ? (
        <Alert
          role={activeNotice.status === 'error' ? 'alert' : 'status'}
          variant={activeNotice.status === 'error' ? 'destructive' : 'default'}
        >
          <AlertDescription>{activeNotice.message}</AlertDescription>
        </Alert>
      ) : null}
      <FeaturePackLimitations
        limitations={account.status === 'ready' ? account.limitations : undefined}
      />
      <FeaturePackBoundary
        emptyDescription='Sign in before opening your account.'
        emptyTitle='No active account'
        resource={account}
      >
        {(data) => {
          const showSecurity =
            (canPerform(policy, 'changePassword') && Boolean(actions?.changePassword)) ||
            (canPerform(policy, 'requestAccountDeletion') &&
              Boolean(actions?.requestAccountDeletion));
          const connectedAccounts = data.connectedAccounts ?? [];
          const showConnections = connectedAccounts.length > 0;
          const sessions = data.sessions ?? [];
          const showSessions = sessions.length > 0;
          const sections: AuthAccountSection[] = ['profile'];
          if (showSecurity) sections.push('security');
          if (showConnections) sections.push('connected-accounts');
          if (showSessions) sections.push('sessions');
          const activeSection = sections.includes(section) ? section : 'profile';
          const multiSection = sections.length > 1;

          return (
            <div className='flex flex-col gap-6'>
              <IdentityHero
                identity={data.identity}
                onSignOut={
                  canPerform(policy, 'signOut') && actions?.signOut
                    ? () => void run('signOut', actions.signOut!, 'You could not be signed out.')
                    : undefined
                }
                signOutPending={pendingAction === 'signOut'}
              />
              {actionError?.key === 'signOut' ? (
                <ActionError message={actionError.message} />
              ) : null}

              {data.identity.emailVerified === false &&
              canPerform(policy, 'sendVerificationEmail') &&
              actions?.sendVerificationEmail ? (
                <VerificationBanner
                  message={verificationMessage}
                  pending={pendingAction === 'verificationEmail'}
                  onSend={() => {
                    setVerificationMessage(undefined);
                    void run(
                      'verificationEmail',
                      () => actions.sendVerificationEmail!({
                        email: data.identity.primaryEmail
                      }),
                      'The verification email could not be sent.',
                      () => setVerificationMessage({
                        kind: 'success',
                        text: 'Verification email sent.'
                      }),
                      (message) => setVerificationMessage({ kind: 'error', text: message })
                    );
                  }}
                />
              ) : null}

              {multiSection ? (
                <Tabs
                  onValueChange={(value) => changeSection(value as AuthAccountSection)}
                  value={activeSection}
                >
                  <TabsList
                    aria-label='Account sections'
                    className='bg-transparent h-auto w-full justify-start gap-1 overflow-x-auto rounded-none border-b border-border/60 p-0'
                  >
                    <TabsTrigger className={sectionTriggerClass} value='profile'>
                      Profile
                    </TabsTrigger>
                    {showSecurity ? (
                      <TabsTrigger className={sectionTriggerClass} value='security'>
                        Security
                      </TabsTrigger>
                    ) : null}
                    {showConnections ? (
                      <TabsTrigger className={sectionTriggerClass} value='connected-accounts'>
                        Connections
                        <span className='text-muted-foreground ml-1.5 tabular-nums text-xs'>
                          {connectedAccounts.length}
                        </span>
                      </TabsTrigger>
                    ) : null}
                    {showSessions ? (
                      <TabsTrigger className={sectionTriggerClass} value='sessions'>
                        Sessions
                        <span className='text-muted-foreground ml-1.5 tabular-nums text-xs'>
                          {sessions.length}
                        </span>
                      </TabsTrigger>
                    ) : null}
                  </TabsList>

                  <TabsContent className='mt-6' value='profile'>
                    <ProfileSection
                      data={data}
                      displayName={displayName}
                      displayNameId={displayNameId}
                      onDisplayNameChange={setDisplayName}
                      pending={pendingAction === 'profile'}
                      error={actionError?.key === 'profile' ? actionError.message : undefined}
                      canUpdate={
                        canPerform(policy, 'updateProfile') && Boolean(actions?.updateProfile)
                      }
                      onSave={() => {
                        const name = displayName.trim();
                        if (!name || !actions?.updateProfile) return;
                        void run(
                          'profile',
                          () => actions.updateProfile!({ displayName: name }),
                          'Your profile could not be updated.',
                          () => setDisplayName('')
                        );
                      }}
                    />
                  </TabsContent>

                  {showSecurity ? (
                    <TabsContent className='mt-6' value='security'>
                      <div className='flex flex-col gap-8'>
                        {canPerform(policy, 'changePassword') && actions?.changePassword ? (
                          <SecuritySection
                            currentPassword={currentPassword}
                            currentPasswordId={currentPasswordId}
                            newPassword={newPassword}
                            newPasswordId={newPasswordId}
                            passwordPolicy={passwordPolicy}
                            pending={pendingAction === 'password'}
                            error={actionError?.key === 'password' ? actionError.message : undefined}
                            showCurrentPassword={showCurrentPassword}
                            showNewPassword={showNewPassword}
                            onCurrentPasswordChange={setCurrentPassword}
                            onNewPasswordChange={setNewPassword}
                            onToggleCurrent={() => setShowCurrentPassword((v) => !v)}
                            onToggleNew={() => setShowNewPassword((v) => !v)}
                            onSubmit={() => {
                              void run(
                                'password',
                                () => actions.changePassword!({
                                  currentPassword,
                                  newPassword
                                }),
                                'Your password could not be changed.',
                                () => {
                                  setCurrentPassword('');
                                  setNewPassword('');
                                }
                              );
                            }}
                          />
                        ) : null}
                        {canPerform(policy, 'requestAccountDeletion') &&
                        actions?.requestAccountDeletion ? (
                          <>
                            {canPerform(policy, 'changePassword') && actions?.changePassword ? (
                              <Separator />
                            ) : null}
                            <AccountDeletionSection
                              identity={data.identity}
                              key={`account-deletion-${data.identity.id}`}
                              onError={onError}
                              requestAccountDeletion={actions.requestAccountDeletion}
                            />
                          </>
                        ) : null}
                      </div>
                    </TabsContent>
                  ) : null}

                  {showConnections ? (
                    <TabsContent className='mt-6' value='connected-accounts'>
                      <ConnectedAccountsSection
                        accounts={connectedAccounts}
                        disconnect={
                          canPerform(policy, 'disconnectConnectedAccount')
                            ? actions?.disconnectConnectedAccount
                            : undefined
                        }
                        key={`connected-accounts-${data.identity.id}`}
                        onError={onError}
                      />
                    </TabsContent>
                  ) : null}

                  {showSessions ? (
                    <TabsContent className='mt-6' value='sessions'>
                      <SessionsSection
                        sessions={sessions}
                        pendingAction={pendingAction}
                        canRevoke={
                          canPerform(policy, 'revokeSession') && Boolean(actions?.revokeSession)
                        }
                        onRevokeRequest={(session) =>
                          setSessionToRevoke({
                            id: session.id,
                            deviceLabel: session.deviceLabel
                          })
                        }
                      />
                    </TabsContent>
                  ) : null}
                </Tabs>
              ) : (
                <ProfileSection
                  data={data}
                  displayName={displayName}
                  displayNameId={displayNameId}
                  onDisplayNameChange={setDisplayName}
                  pending={pendingAction === 'profile'}
                  error={actionError?.key === 'profile' ? actionError.message : undefined}
                  canUpdate={
                    canPerform(policy, 'updateProfile') && Boolean(actions?.updateProfile)
                  }
                  onSave={() => {
                    const name = displayName.trim();
                    if (!name || !actions?.updateProfile) return;
                    void run(
                      'profile',
                      () => actions.updateProfile!({ displayName: name }),
                      'Your profile could not be updated.',
                      () => setDisplayName('')
                    );
                  }}
                />
              )}

              {canPerform(policy, 'revokeSession') && actions?.revokeSession ? (
                <AlertDialog
                  onOpenChange={(open) => {
                    if (!open && pendingAction !== sessionToRevoke?.id) {
                      const sessionId = sessionToRevoke?.id;
                      setSessionToRevoke(undefined);
                      setActionError((current) =>
                        current?.key === sessionId ? undefined : current
                      );
                    }
                  }}
                  open={Boolean(sessionToRevoke)}
                >
                  <AlertDialogContent>
                    <AlertDialogHeader>
                      <AlertDialogTitle>Revoke {sessionToRevoke?.deviceLabel}?</AlertDialogTitle>
                      <AlertDialogDescription>
                        This signs that device out of your account. You will need to authenticate there again.
                      </AlertDialogDescription>
                    </AlertDialogHeader>
                    {sessionToRevoke && actionError?.key === sessionToRevoke.id ? (
                      <ActionError message={actionError.message} />
                    ) : null}
                    <AlertDialogFooter>
                      <AlertDialogCancel disabled={pendingAction === sessionToRevoke?.id}>
                        Cancel
                      </AlertDialogCancel>
                      <Button
                        disabled={!sessionToRevoke || pendingAction === sessionToRevoke.id}
                        onClick={() => {
                          if (!sessionToRevoke) return;
                          const sessionId = sessionToRevoke.id;
                          void run(
                            sessionId,
                            () => actions.revokeSession!({ sessionId }),
                            'The session could not be revoked.',
                            () => setSessionToRevoke(undefined)
                          );
                        }}
                        variant='destructive'
                      >
                        {pendingAction === sessionToRevoke?.id ? 'Revoking…' : 'Revoke session'}
                      </Button>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              ) : null}
            </div>
          );
        }}
      </FeaturePackBoundary>
    </div>
  );
}

