function ProfileSection({
  data,
  displayName,
  displayNameId,
  onDisplayNameChange,
  canUpdate,
  pending,
  error,
  onSave
}: Readonly<{
  data: AuthAccountData;
  displayName: string;
  displayNameId: string;
  onDisplayNameChange: (value: string) => void;
  canUpdate: boolean;
  pending: boolean;
  error?: string;
