          <Button
            aria-busy={pending}
            className='self-start'
            disabled={!displayName.trim() || pending}
            size='sm'
            type='submit'
          >
            {pending ? 'Saving changes…' : 'Save changes'}
          </Button>
          {error ? <ActionError message={error} /> : null}
        </form>
      ) : (
        <p className='text-sm'>
          <span className='text-muted-foreground'>Current name · </span>
